module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg clk;
    reg reset;
    wire [3:0] ena;
    wire [15:0] q;

    // 2. Instantiate TopModule dut ( ... );
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .ena(ena),
        .q(q)
    );

    // 3. Stimulus & self-checking:
    integer errors = 0;

    // Clock generation
    always #5 clk = ~clk; // 10 time units clock period

    initial begin
        // Initialize inputs
        clk = 0;
        reset = 1; // Assert reset
        #10 reset = 0; // Deassert reset

        // Test sequence
        // Check initial state
        if (q !== 16'b0000000000000000 || ena !== 4'b0000) begin
            $display("Error: Initial state mismatch.");
            errors = errors + 1;
        end

        // Run the counter for a few cycles
        repeat (20) begin
            #10; // Wait for a clock cycle
            if (q !== {dut.thousands, dut.hundreds, dut.tens, dut.ones}) begin
                $display("Error: Output q mismatch at time %t: expected %b, got %b", $time, {dut.thousands, dut.hundreds, dut.tens, dut.ones}, q);
                errors = errors + 1;
            end
            // Check enable signals
            if (q[3:0] == 4'b0000 && ena[0] !== 0) begin
                $display("Error: ena[0] should be 0 when ones is 0 at time %t", $time);
                errors = errors + 1;
            end
            if (q[7:4] == 4'b0000 && ena[1] !== 0) begin
                $display("Error: ena[1] should be 0 when tens is 0 at time %t", $time);
                errors = errors + 1;
            end
            if (q[11:8] == 4'b0000 && ena[2] !== 0) begin
                $display("Error: ena[2] should be 0 when hundreds is 0 at time %t", $time);
                errors = errors + 1;
            end
            if (q[15:12] == 4'b0000 && ena[3] !== 0) begin
                $display("Error: ena[3] should be 0 when thousands is 0 at time %t", $time);
                errors = errors + 1;
            end
        end

        // Final check for expected maximum value
        #10;
        if (q !== 16'b0000000001001000) begin // 9999 in BCD
            $display("Error: Final output q mismatch: expected 9999, got %b", q);
            errors = errors + 1;
        end

        // Display test result
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end
endmodule
